Rules.InvariantScript:
// Wenn ein aktiver Auftrag verfolgt wird: aktuellen Status nachladen
// ❗ Dataverse: If(!IsBlank(gActiveTrip), Set(gActiveTrip, LookUp(PetraTrips, ID = gActiveTrip.ID)))
Set(gLastRefresh, Text(Now(), "[$-de-DE]hh:mm:ss"))

If(!IsBlank(gActiveTrip),
    // ❗ Dataverse: Set(gActiveTrip, LookUp(PetraTrips, ID = gActiveTrip.ID))
    // Demo: aktuellen Status aus gTrips lesen
    Set(gActiveTrip, LookUp(gTrips, ID = gActiveTrip.ID));
    Set(gLastRefresh, Text(Now(), "[$-de-DE]hh:mm:ss"))
)

If(!IsBlank(gActiveTrip) And gActiveTrip.Status = "pending",
    // Auftrag stornieren
    UpdateIf(gTrips, ID = gActiveTrip.ID, {Status: "cancelled"})
);
Set(gActiveTrip, Blank());
Set(gEmployeeFormError, "")

// Validierung
Set(gEmployeeFormError, "");
If(Left(PickupZoneDropdown.SelectedText.Value, 1) = Left(DropoffZoneDropdown.SelectedText.Value, 1),
    Set(gEmployeeFormError, "Abholzone und Zielzone müssen verschieden sein.");
    false,
    // ❗ Dataverse: Collect(PetraTrips, {...}); Set(gActiveTrip, Last(PetraTrips))
    Collect(gTrips, {
        ID:             gNextTripID,
        PickupZone:     Left(PickupZoneDropdown.SelectedText.Value, 1),
        PickupDetail:   PickupDetailInput.Text,
        DropoffZone:    Left(DropoffZoneDropdown.SelectedText.Value, 1),
        DropoffDetail:  DropoffDetailInput.Text,
        Passengers:     Round(PassengerSlider.Value, 0),
        Status:         "pending",
        OverflowWarning: false,
        TaxiFunkID:     "",
        TaxiID:         0,
        TaxiPosition:   "",
        RequestedAt:    Text(Now(), "hh:mm")
    });
    Set(gNextTripID, gNextTripID + 1);
    Set(gActiveTrip, LookUp(gTrips, ID = gNextTripID - 1))
)
